/*
 * Suivi Dossiers — Aide.
 * Scripts chargés dans l'ordre par index.html ; ils partagent la portée globale (voir js/app/README.md).
 */
'use strict';

// ---------------------------------------------------------------------------
// Aide
// ---------------------------------------------------------------------------

function viewAide() {
  const item = (title, html, open) => `<details class="card help"${open ? ' open' : ''}><summary><h2>${title}</h2></summary><div class="help-body">${html}</div></details>`;
  return `
    <div class="page-head"><h1>Aide</h1><span class="badge">Version ${ASSET_VERSION}</span></div>
    ${item(`Nouveautés des versions 29 à ${ASSET_VERSION}`, `<ul>
      <li><strong>Paie</strong> (Espace FEC → onglet « Paie », ou bouton « Faire le cadrage de la paie » du cycle H) : cadrage de la paie. Déposez le récapitulatif de paie de SILAE (« Ouvrir dans tableur », enregistré en Excel) ou le journal de paie en PDF, le détail des cotisations (Excel ou PDF), le FEC de l'exercice, déposé tel quel (ouvert depuis le cycle H, le FEC analysé est déjà repris ; les écritures de paie y sont repérées automatiquement, quel que soit le journal : toute écriture qui mouvemente un 645 ou crédite le 421 ; un grand livre Excel du journal de paie reste accepté) et, facultatif, le solde de repos à la clôture (PDF ou Excel). Chaque compte est rapproché de la paie : 641 du brut (hors congés payés : 6412 et comptes dont le libellé cite les congés), chaque 645 de la part patronale de ses organismes (rattachés automatiquement, modifiables ; le choix est retenu par le nom de l'organisme), 6312, 6333 et 6335 des contributions formation et apprentissage (comptabilisées dans un 645, elles reçoivent un motif automatique « à reclasser »), 421 du net, 43x et 442 des cotisations de leurs organismes, 4282 et 4382 de l'indemnité et des charges du solde de repos ; le détail mensuel (récapitulatif Excel) montre où naît l'écart. Dans une édition PDF, la ligne retenue (brut, net, congés payés) se change dans la carte du compte ; le choix vaut pour les éditions suivantes du cabinet. Rattaché à un dossier (analyse du cycle H, ou FEC dont le SIREN est celui d'un dossier), le cadrage est enregistré chiffré dans la feuille de l'exercice : rattachements, motifs et reclassements sont repris à la réouverture, et sa synthèse alimente le cycle H (contrôles, pièces lues, colonne « Selon pièce » de 4282 et 4382). Chaque compte reçoit sa note (SILAE / logiciel, écart, motif, solde à la clôture, mois non réglés), à copier une par une ou toutes ensemble. Les écarts reçoivent des motifs automatiques (contributions formation passées en classe 63), des pistes (montant retrouvé dans un autre compte, mois ou ligne de cotisation de même montant) et vos motifs saisis ; deux écarts opposés se reclassent d'un clic, avec l'écriture de reclassement à passer. Les fichiers Excel au format .xls (ancien format) sont désormais lus partout dans l'application.</li>
      <li><strong>Rapprochement et relevés PDF : toutes les banques.</strong> Relevés PDF lus d'après leurs colonnes, quelle que soit la banque (BNP Paribas, Société Générale, LCL, Crédit Agricole, Crédit Mutuel / CIC, La Banque Postale, Caisse d'Épargne, banques en ligne…) : en-têtes « Débit / Crédit », « Dépenses / Recettes », « Argent sortant / entrant », « Money out / in » ou un seul « Montant » signé, colonne « Solde », dates avec ou sans l'année ou en lettres, montant sur la ligne suivant la date, « Totaux », « Solde créditeur au ». Sans en-tête reconnu, les colonnes de montants sont déduites de leur position et la lecture n'est retenue que si elle retrouve au centime les soldes ou les totaux du relevé. Fichiers : CSV et Excel des banques en ligne (en-têtes français ou anglais, colonne « Sens », sans ligne d'en-tête, opérations en attente ou annulées écartées, frais déduits, soldes repris), QIF, MT940, CAMT.052 / 054, en plus d'OFX, CAMT.053 et CFONB.</li>
      <li><strong>Cotisations TNS</strong> (menu « Cotisations TNS », ou depuis la fiche du dossier) : régularisation des cotisations sociales des travailleurs non salariés à la clôture. Choisissez le profil (gérant à l'IR, gérant de société à l'IS, kinésithérapeute avec la CARPIMKO, pharmacien avec la CAVP, architecte), saisissez la date de clôture, le revenu N-1 et l'avis de l'Urssaf (et de la caisse) : l'outil recalcule les définitives N-1 et les provisionnelles N avec les barèmes 2025-2026 de la réforme de l'assiette pour contrôler l'avis, calcule le reste dû ou le trop-versé à la clôture (régularisation N-1 restant à payer, quote-part N rattachée à l'exercice, provisionnelles payées), propose les écritures (646 / 4386 ou 4387, extourne du bilan précédent) et détaille les cotisations. Le rapport s'imprime ou s'enregistre en PDF. La saisie est conservée dans le dossier choisi.</li>
      <li><strong>Échéances qui tombent un week-end ou un jour férié</strong> : reportées au premier jour ouvré suivant pour le retard. Une TVA due le dimanche 15 n'est en retard qu'à partir du mardi 17, partout (suivi mensuel, missions, tableau de bord, agenda). La date saisie ou importée reste inchangée, et le report est indiqué (« échéance du dimanche 15/11 reportée au premier jour ouvré »). Jours fériés : 1er janvier, lundi de Pâques, 1er et 8 mai, Ascension, lundi de Pentecôte, 14 juillet, 15 août, 1er et 11 novembre, 25 décembre. L'occurrence suivante d'une mission récurrente repart de la date légale (jour limite TVA du dossier, le 15 pour les acomptes et la CFE), sans reconduire le report.</li>
      <li><strong>Lettrage : visa des hypothèses, mails de bilan, de situation et de révision mensuelle.</strong> Cochez le visa d'une hypothèse (règlement resté ouvert, facture de même montant sur un autre compte du même fournisseur) : le règlement est transféré sur le compte proposé et lettré avec ses factures (lien vers le compte, mention « transféré de » dans le tableau, colonne Visa dans l'export Excel) ; les visas restent en mémoire jusqu'à « Effacer » ou au verrouillage. Nouvel encadré « Mails de situation et de révision » : cochez Bilan ou Situation (date de clôture, nom de la société, repris du dossier pour un FEC, début d'exercice) pour obtenir un mail de demande d'extrait de compte par fournisseur dont le lettrage pose problème (règlement sans facture, avoir ouvert, doublon, hypothèse non visée), ou Révision mensuelle pour le mail général des factures manquantes à la date choisie. Chaque mail est modifiable et se copie seul ou tous ensemble.</li>
      <li><strong>Lettrage plus complet, fournisseurs à échéance M+1.</strong> Un règlement peut solder jusqu'à 60 factures qui se suivent (l'écart de dates réglable reste la limite) ; un règlement qui n'a qu'une suite de factures possible passe avant les autres ; 2 ou 3 factures non consécutives, peu espacées, sont lettrées quand la combinaison est la seule possible (à vérifier) ; 2 ou 3 factures qui se suivent se lettrent avec 2 règlements postérieurs. Les avoirs sont pris en compte partout : un avoir déduit du règlement peut suivre les factures ou être arrivé un peu avant ou après elles (dans l'écart de dates), y compris dans les lots réglés en deux fois et pour le compte d'attente. Indiquez dans les réglages les fournisseurs réglés le mois suivant (noms ou codes) : un règlement du mois M+1 ne solde alors que des factures du mois M. Comme partout, un règlement n'est jamais lettré avec une facture postérieure.</li>
      <li><strong>Écritures LCR pour ACD</strong> (menu « Écritures LCR », ou Espace FEC → onglet « Lettrage et LCR » → « Écritures LCR », où le FEC ouvert sert de listing) : déposez le listing fournisseurs du dossier (Excel ou CSV, ou le FEC du dossier) et les relevés LCR en PDF (relevé d'effets à payer du Crédit Agricole, relevé de lettres de change du CIC) ; chaque tireur est rapproché d'un compte du listing, vos corrections, le listing et les réglages sont retenus pour le dossier et repris le mois suivant, et l'outil prépare une OD par relevé et le fichier d'import ACD.</li>
      <li><strong>Lettrage : nouvelle version de l'outil.</strong> Chaque règlement solde des factures qui se suivent, toutes datées au plus tard de son jour et peu espacées (45 jours au plus entre la première et la dernière, réglable), les plus anciennes d'abord. L'outil repère aussi le relevé saisi en plus de ses factures (lettrage surligné en violet, relevé à annuler), les factures et avoirs réglés ensemble, l'avoir qui annule des factures, la facture de 4 000 € et plus réglée en plusieurs fois, le règlement dont la facture est sur un autre compte du même fournisseur (hypothèse), les doublons de factures, les montants du compte d'attente (LCR…) à affecter à un fournisseur, et prépare le mail des factures manquantes. Un compte lettré de votre côté se ferme d'un clic : il quitte la liste et le mail.</li>
      <li><strong>Lettrage proposé</strong> (Espace FEC → onglet « Lettrage », qui reprend le FEC ouvert ; ou menu « Lettrage (grand livre) » pour un grand livre PDF sans FEC) : déposez le grand livre non lettré (PDF de l'édition « Grands-livres », ou son texte collé) ou un FEC. Compte par compte, chaque règlement (dans l'ordre des dates, ceux qui n'ont qu'une possibilité d'abord) solde des factures qui se suivent (jusqu'à 60), datées au plus tard de son jour et peu espacées (écart maximal réglable), les plus anciennes d'abord ; puis relevé saisi en plus de ses factures (même total que le règlement : lettré avec elles mais à annuler), factures et avoirs réglés ensemble, avoir qui annule des factures, facture de 4 000 € et plus réglée en plusieurs fois (règlements consécutifs, ou deux ou trois règlements dans les 90 jours, à vérifier), 2 ou 3 factures non consécutives peu espacées quand la combinaison est la seule possible (à vérifier), 2 ou 3 factures qui se suivent réglées par 2 règlements postérieurs. Un avoir peut faire partie du lot : qui se suit avec les factures, ou arrivé un peu avant ou après elles (dans l'écart de dates) quand la combinaison est la seule possible. Les fournisseurs « à factures non consécutives » indiqués acceptent des factures qui ne se suivent pas ; pour les fournisseurs « à échéance M+1 », un règlement ne solde que des factures du mois précédent. Sur l'ensemble des comptes : hypothèses (règlement resté ouvert, facture de même montant sur un autre compte du même tiers), doublons (même n° et même montant ; même compte, même date et même montant), compte d'attente (code ou nom indiqué, LCR par défaut) dont chaque montant est rapproché des factures ouvertes d'un fournisseur, et mail des règlements sans facture, modifiable et à copier (comptes exclus indiqués). Les comptes dont le code ou le nom contient un des mots « ignorés » (BNC par défaut) sont écartés. Une hypothèse visée transfère le règlement sur le compte proposé, où il est lettré avec les factures. Mails de bilan ou de situation (demande d'extrait de compte aux fournisseurs dont le lettrage pose problème) et de révision mensuelle (factures manquantes). Un compte lettré de votre côté se ferme (bouton « Fermer ce compte ») et se rouvre en bas de page. Grand livre : seules les écritures des journaux d'achat et de règlement indiqués sont lettrées (le sens se lit dans le solde progressif ; un à-nouveau qui cite son journal d'origine, « 15/12/2025 -AC- », le reprend). FEC : seules les lignes non lettrées des fournisseurs (401, 404) ou des clients (411) sont reprises, une écriture de banque étant un règlement et une écriture de charges ou de produits une facture ; le FEC ouvert dans l'analyse s'utilise d'un clic. Copie des lettrages pour un tableur, export Excel (lettrages, écritures ouvertes, synthèse, hypothèses, compte d'attente, relevés, doublons, règlements sans facture). Rien n'est conservé, sauf les réglages.</li>
      <li><strong>Contrôle TVA : import des CA3, créances par taux, OD de régularisation, portefeuille.</strong> Importez les déclarations déposées (PDF du formulaire 3310-CA3-SD) pour reprendre les montants exacts dans le récapitulatif ; les créances et avances clients par taux se calculent d'après le lettrage des comptes clients, ou s'importent d'une liste de factures non réglées (Excel, CSV) ; une OD de régularisation est proposée pour chaque écart des soldes de TVA après OD, exportable pour ACD ou Pennylane ; le portefeuille (plusieurs FEC) donne le contrôle de la TVA de chaque dossier, du plus grand écart au plus petit.</li>
      <li><strong>Contrôle de la TVA de l'exercice</strong> (Espace FEC → onglet « TVA » → « Contrôle TVA ») : la feuille de travail TVA du cabinet, remplie d'après le FEC, du début de l'exercice au mois d'arrêté. Récapitulatif des déclarations pré-rempli d'après les OD de TVA (base = TVA ÷ taux, crédit reporté, écart avec l'OD), chiffre d'affaires par taux et contrôle en bases, TVA sur les encaissements, TVA déductible moins celle des prestations non réglées, soldes de TVA après OD. Chaque case se corrige ; les saisies restent dans le dossier ; export Excel en quatre feuilles.</li>
      <li><strong>Factures de vente numérotées « n° + mois et année »</strong> (XXXXMMAA : 51080126 = facture 5108 de janvier 2026), comme le font certains logiciels d'hôtellerie ou de location : l'onglet « Factures de vente » de l'espace Mois reconnaît cette notation dans tous les libellés, ventes et encaissements, que la saisie ait ajouté un F devant ou non, y compris les listes (« 5101-5102-51040126 », « F5113+5114+51150226 », « F5175,5176,51770526 ») et les libellés tronqués. Les n° sont affichés comme sur la facture (51070126) ; pour un n° manquant, le mois et l'année sont ceux des factures voisines, ou les deux possibilités quand le trou est à cheval sur deux mois. Les n° cités nulle part sont signalés manquants mois par mois et ajoutés aux pièces à demander ; les n° vus seulement dans un encaissement sont listés. Une case « Contrôler » par série permet d'écarter une série qui n'est pas la numérotation des factures (n° interne de pièce, de réservation…).</li>
      <li><strong>Rapprocher un relevé</strong> (Espace FEC → onglet « Rapprochement bancaire » → « Relevé du mois détaillé », avec le FEC du journal de banque ou le FEC complet) : déposez le relevé bancaire du mois (PDF, CSV, Excel, OFX, CAMT.053, CFONB) et le FEC exporté pour le seul journal de banque. L'application liste les opérations non comptabilisées (avec le compte à utiliser), les écritures absentes du relevé, les montants différents (chiffres inversés compris), les sens inversés et les doublons, chiffre l'état de rapprochement et exporte les écritures manquantes pour ACD ou Pennylane.</li>
      <li><strong>Suivi mensuel : filtre « Avancement »</strong>. Choisissez « À terminer » et un mois : les dossiers dont la TVA (ou toute autre mission) de ce mois est terminée sont masqués, pour ne garder que ce qui reste à faire. Aussi « En retard » et « Terminés ».</li>
      <li><strong>Pièces manquantes cumulées</strong> (Espace FEC, onglet Mois) : la liste reprend tout ce qui manque depuis le début de l'exercice jusqu'à la fin du mois choisi, d'après le FEC actuel (en août : de l'ouverture de l'exercice au 31 août). Trois blocs : <em>À demander</em> (pièces jamais demandées), <em>Déjà demandées, en attente du client</em> (avec la date d'envoi et un bouton « Reçue ») et <em>Écartées</em> (pièces décochées lors d'une demande, à remettre d'une case). Une pièce reste proposée tant qu'elle manque dans le FEC, même cochée reçue : elle disparaît une fois comptabilisée. La demande mensuelle du dossier est unique : « Compléter la demande en cours » y ajoute les nouvelles pièces, et le mail liste toutes les pièces manquantes en une seule liste. L'étape « Pièces reçues » des missions TVA ou saisie est cochée mois par mois, dès que toutes les pièces jusqu'à ce mois sont reçues. Une pièce demandée puis comptabilisée (facture saisie, opération reclassée) est signalée « comptabilisée depuis la demande » et se coche en un clic. Les demandes mensuelles des versions précédentes sont reprises dans la demande unique, sans valoir réception.</li>
      <li><strong>Comptes d'attente</strong> : le moteur écarte les lignes déjà lettrées, reclassées par une OD (une à une, ou une OD pour les opérations du mois) ou d'un compte soldé ; seules les opérations de banque ou de caisse restées ouvertes sont demandées au client. Pour un très gros fichier, les listes gardent les opérations les plus récentes et l'écran l'indique.</li>
      <li><strong>Pièces à demander : opérations en compte d'attente rangées par rubrique</strong>. Chaque opération en 47 porte un menu : <em>Ventes et encaissements</em>, <em>Factures fournisseurs</em> ou <em>Opérations diverses</em>. La rubrique proposée suit l'affectation déjà utilisée pour le même libellé (fournisseur, client, charge), sinon le sens de l'opération (encaissement → ventes, paiement → factures fournisseurs) ; votre choix est conservé dans le dossier pour les analyses suivantes. Le client reçoit une demande de facture, de facture de vente, d'avoir ou de justificatif, et non plus une liste d'« opérations à identifier ».</li>
      <li><strong>Liste Excel pour le client</strong> refaite comme un document du cabinet : titre, dossier et période, date de la demande et échéance, explication, récapitulatif par rubrique, une rubrique par bandeau, libellé de l'écriture, date et montant de chaque opération dans leurs colonnes (une ligne par paiement quand une facture en regroupe plusieurs ; le document demandé ne reprend plus le nom du compte ou du tiers), une ligne numérotée par écriture, document demandé selon la rubrique (factures fournisseurs : facture d'un paiement, avoir d'un encaissement ; ventes et encaissements : l'inverse), colonne « Transmis » en case à cocher Excel (verte une fois cochée), tableau « Autres documents » de trois lignes vides à compléter et « Vos commentaires » à remplir. Sans quadrillage, en paysage sur une page de large, pied de page avec le cabinet et la pagination.</li>
      <li><strong>Contrôle de TVA : brouillon de CA3 au formulaire en vigueur</strong>. Les lignes suivent la 3310-CA3-SD actuelle : A1 (ventes), A2, E1 (exportations), E2, F2 (livraisons intracommunautaires) ; le 2,1 % des pharmacies en <strong>ligne T6</strong> (France continentale ; ligne 11 dans les DOM). Autoliquidation : la base est lue sur l'écriture d'achat (et non plus estimée à 20 %), les biens en ligne B2 avec la TVA reprise en ligne 17, les services en ligne A3, et la base ajoutée à la ligne du taux (08…).</li>
      <li><strong>Comparer deux FEC</strong> (Espace FEC → Plus) : un FEC de référence (celui qui a été déclaré, par exemple l'export d'ACD) et un autre FEC du même exercice (par exemple celui de Pennylane). L'application liste les écritures absentes du FEC comparé, celles qui y sont en plus, les écritures modifiées (date, montant, compte, lignes), et compare la balance, les tiers et les à-nouveaux, malgré des numéros de comptes, de journaux et de pièces différents d'un logiciel à l'autre. Export Excel.</li>
      <li><strong>Relevés PDF → Excel</strong> (menu « Relevés PDF → Excel ») : déposez un ou plusieurs relevés bancaires en PDF (édition « Relevé bancaire » d'ACD : Date, Opérations, Dépenses, Recettes, ou mises en page Débit / Crédit) ; l'application en tire un fichier Excel prêt pour l'import de transactions bancaires (Date, Libellé, Montant signé, ou Débit et Crédit). Les libellés sur deux lignes sont réunis, les totaux et le solde final sont contrôlés. Le relevé PDF s'importe aussi directement dans Révision → Rapprochement.</li>
      <li><strong>Factures de vente du mois</strong> (Espace FEC → onglet « Mois » → « Factures de vente ») : toutes les écritures de produits 70, 75 et 77, factures et avoirs, par série ; numéros manquants, doublons, ordre chronologique, et la liste de toutes les ventes du mois. Le n° de facture est lu dans le n° de pièce, ou dans le libellé (« Facture FV-0207 … ») quand la pièce porte le n° d'écriture. FEC Pennylane : le n° est lu dans le libellé de la ligne client 411 (« Facture X - F-260010 », « Avoir X - F-260011 »). Chaque facture manquante est listée sur sa propre ligne, avec son statut et son commentaire (annulée, non saisie…).</li>
      <li><strong>Anonymiser un FEC</strong> (Espace FEC → Plus) : pour envoyer un FEC réel sans donnée identifiante. Par défaut, seuls les noms des clients, des personnes de l'entreprise (salariés, associés, dirigeants) et du dossier sont remplacés, par des pseudonymes cohérents ; IBAN, téléphones, e-mails et SIREN sont masqués ; fournisseurs, montants, encodage et structure sont conservés. Relisez les mots conservés et l'aperçu avant de télécharger.</li>
      <li><strong>FEC Pennylane</strong> : la date de validation vide d'un export en cours d'exercice n'est plus une anomalie de conformité ; libellés bancaires raccourcis (tête et communication, sans IBAN, BIC ni mandat) ; TVA sur les encaissements : la TVA exigible est celle virée en TVA collectée au règlement (journal RT), la TVA déductible sur encaissements (44564) n'est déduite qu'au paiement, et le chiffre d'affaires est rapproché de la TVA facturée ; extournes de PCA et de factures à établir écartées du contrôle des ventes ; ancienneté des créances reprises en à-nouveau lue dans leur libellé.</li>
      <li><strong>Encaissements en attente qui citent une facture</strong> (« VIR … F260012 ») : la facture client est retrouvée (factures du FEC et à-nouveaux) et le reclassement vers le compte du client est proposé ; aucun justificatif n'est demandé pour ces opérations.</li>
      <li><strong>Affectations suggérées</strong> : une opération en compte d'attente (Contrôles de saisie) ou du relevé non comptabilisée (Révision → Rapprochement) reçoit le compte déjà utilisé pour le même libellé, lettré pour un compte de tiers ; l'écriture de reclassement est proposée dans Révision → Écritures.</li>
      <li><strong>Contrôle de la TVA refait</strong> sur les comptes (Espace FEC → TVA → TVA du mois).</li>
    </ul>`, true)}
    ${item('Premiers pas', `<ol>
      <li><strong>Paramètres</strong> : renseignez le nom du cabinet, votre prénom, vos collaborateurs et votre signature.</li>
      <li><strong>Dossiers → Importer</strong> : importez votre tableau Excel de suivi (ou créez les dossiers un par un).</li>
      <li><strong>Calendrier fiscal</strong> : créez en un clic les échéances de l'année de tous vos dossiers.</li>
      <li><strong>Sauvegarde</strong> : activez la sauvegarde automatique (sur ordinateur) ou exportez une sauvegarde chiffrée chaque semaine.</li>
    </ol>`, true)}
    ${item('Au quotidien', `<ul>
      <li>Le <strong>tableau de bord</strong> montre d'abord ce qui demande une action : missions en retard, à venir dans les 14 jours et en attente du client (avec celles à relancer), puis « Reprendre » (derniers dossiers et outils ouverts) et les missions à valider ; la conformité des dossiers (lettre de mission, LCB-FT) est en bas. Choisissez « Mes dossiers » pour ne voir que votre portefeuille : ce choix s'applique aussi aux missions, au suivi mensuel et au calendrier fiscal.</li>
      <li>Cliquez sur une mission pour cocher ses étapes : elle passe « en cours » à la première étape cochée, et « terminée » à la dernière. Le bouton <strong>✓ Terminée</strong> valide tout d'un coup.</li>
      <li>Les missions récurrentes (TVA, paie, acomptes…) créent automatiquement l'occurrence suivante lorsqu'elles sont terminées.</li>
      <li><strong>Étapes cochées automatiquement</strong> (signalées « automatique » dans la mission et notées au journal du dossier) : la demande de pièces mensuelle coche l'étape « Pièces reçues » de la TVA ou de la saisie mois par mois, dès que toutes les pièces demandées jusqu'à ce mois sont reçues (une étape décochée à la main ne l'est plus automatiquement), et une demande de situation ou de bilan entièrement reçue coche celle de la situation ou du bilan ; quand les quatre cycles sont marqués « revus » dans la feuille de travail, l'étape « Révision des comptes » du bilan (ou de la situation) l'est aussi ; la mission « Revue FEC » suit les points traités dans la feuille de travail.</li>
      <li>Paramètres → <strong>Modèles de missions</strong> : si vous modifiez les étapes d'un modèle, l'application propose de mettre à jour les missions en cours qui ont encore les anciennes étapes (les étapes cochées le restent).</li>
    </ul>`)}
    ${item('Importer le classeur du cabinet', `<p>Dossiers → <strong>Importer</strong>, puis choisissez votre classeur de suivi. S'il contient les onglets INFO DOSSIER, SUIVI TVA, SUIVI RÉVISION, SUIVI SITUATION, SUIVI DÉCLARATION ou SUIVI SAISIE, ils sont tous repris en une fois :</p>
      <ul>
        <li>filtre sur une colonne (ex. <strong>CJ = ABC</strong>), proposé automatiquement si votre prénom ou trigramme figure dans le fichier ;</li>
        <li>les bilans reprennent vos propres étapes de révision (saisie, pointages… envoi EDI, BAT, FN), et une étape cochée coche les précédentes ;</li>
        <li>OK ou montant = fait ; case hachurée, N/A, DISP ou EUX = non applicable ;</li>
        <li>les onglets contenant des identifiants et mots de passe (DGFIP, URSSAF, EBICS) ne sont jamais lus ;</li>
        <li>réimportez le classeur quand vous voulez : rien n'est dupliqué, et aucune case cochée dans l'application n'est décochée.</li>
      </ul>`)}
    ${item('Suivi mensuel (grille)', `<ul>
      <li>Reproduit votre tableau Excel : un dossier par ligne, un mois par colonne. Filtrez par type de mission, régime de TVA (mensuel, trimestriel, CA12) et responsable.</li>
      <li><strong>Avancement</strong> : « À terminer » masque les dossiers dont la mission du mois choisi est terminée (et ceux qui n'ont rien à déclarer ce mois-là, comme les trimestriels hors fin de trimestre) ; « En retard » ne garde que les missions du mois en retard ; « Terminés » ne montre que celles qui sont faites. Le mois proposé est celui que l'on déclare en ce moment (le mois précédent) ; sa colonne est encadrée. Le choix est conservé, et l'export Excel reprend les dossiers affichés.</li>
      <li><strong>Tri</strong> : cliquez sur un titre de colonne (N°, Dossier, TVA, Jour) ou choisissez « Trier par » (clôture, responsable, retards et avancement) ; un second clic inverse l'ordre. Le tri est conservé.</li>
      <li><strong>Étapes</strong> (mode par défaut) : un clic sur une case affiche les étapes de la mission ; cliquez sur une étape faite pour la cocher (les précédentes le sont aussi), recliquez pour la décocher. Pour la TVA, <strong>banque importée</strong>, <strong>banque affectée</strong>, <strong>saisie des ventes</strong> et <strong>saisie des achats</strong> se cochent séparément, dans l'ordre où vous les faites (« Banque affectée » coche aussi « Banque importée »). La case indique la dernière étape faite (« Bq import », « Bq affect », « Ventes », « Achats », puis « Saisie » quand les quatre sont faites), et la dernière étape termine la mission. La fenêtre des étapes reste ouverte pour en cocher plusieurs d'affilée (✕, Échap ou un clic à côté pour la fermer). Survolez une case pour voir toutes les étapes.</li>
      <li>Si une <strong>demande de pièces mensuelle</strong> (Espace FEC, onglet Mois) est en cours, la fenêtre des étapes l'indique avec le nombre de pièces encore attendues jusqu'à la fin du mois de la mission.</li>
      <li><strong>Pointage rapide</strong> : un clic sur une case la passe à OK, un second clic annule, comme dans Excel.</li>
      <li><strong>Montant de la TVA</strong> : dans la fenêtre des étapes (ou la fiche de la mission), notez le montant déclaré : « TVA à payer », « Crédit de TVA » (ou un montant précédé de « - ») ou « Néant ». Il s'affiche sous la case (« 2 450 », « Cr. 560 »), dans la liste des missions et dans l'export Excel (feuille « Montants TVA », positif à payer, négatif crédit). Le montant ne passe pas à l'occurrence suivante. Le net saisi dans le contrôle de TVA du FEC est repris ici, et la validation de ce contrôle note son montant si rien n'est encore saisi.</li>
      <li><strong>Exporter en Excel</strong> produit un fichier réimportable (attention : non chiffré).</li>
    </ul>`)}
    ${item('Calendrier fiscal', `<p>Le bouton <strong>Calendrier fiscal</strong> (tableau de bord, missions, suivi mensuel ou fiche dossier) crée les échéances de l'année selon la forme, le régime de TVA, le régime fiscal et la date de clôture de chaque dossier : TVA, CA12 et acomptes, acomptes et solde d'IS, bilan et liasse, approbation des comptes, CFE. Les dates sont reportées au jour ouvré suivant ; une échéance saisie ou importée qui tombe un samedi, un dimanche ou un jour férié l'est aussi pour le calcul du retard.</p>
      <p class="muted">Les dates sont <strong>indicatives</strong> : vérifiez-les avec le calendrier fiscal officiel. Renseignez le régime fiscal des dossiers pour affiner (l'IS est présumé pour les SARL, SAS, SASU, SA, SELARL, SELAS).</p>`)}
    ${item('Relancer un client', `<ul>
      <li>Depuis une mission ou un dossier, <strong>Écrire au client</strong> prépare un message : demande de documents, relance ou envoi pour validation.</li>
      <li>La liste des documents reprend les étapes non cochées de la mission (« Pièces reçues », « Relevés bancaires reçus »…).</li>
      <li>« Copier le message » ou « Ouvrir dans ma messagerie » : l'envoi est noté dans le journal du dossier et la mission passe « en attente du client ».</li>
      <li>Sans réponse après le délai choisi dans les paramètres (7 jours par défaut), la mission apparaît dans <strong>À relancer</strong>.</li>
    </ul>`)}
    ${item('Espace FEC', `<ul>
      <li>Menu <strong>Espace FEC</strong> (« Travail sur un FEC ») : déposez le fichier des écritures comptables (.txt) d'un dossier. Il est analysé sur l'appareil, sans envoi ni conservation. Tout ce qui s'appuie sur le FEC est dans cet espace : le bandeau rappelle le dossier, l'exercice et le fichier (« Changer de FEC », menu « Plus » : exporter en Excel, enregistrer la synthèse, créer une mission de revue, comparer deux FEC, plusieurs dossiers, anonymiser un FEC), puis les onglets :
        <ul>
          <li><strong>Synthèse</strong> : la liste de travail du FEC. « À traiter sur ce FEC » reprend les anomalies du fichier, les pièces à demander, les points des cycles ni traités ni en attente de pièce et les travaux à faire (paie, immobilisations), chacun avec un bouton vers l'onglet où le traiter ; à côté, l'avancement de chaque cycle A à K et le dossier de travail en PDF. Les points généraux sont repliés en bas.</li>
          <li><strong>Révision A–K</strong> : cycles A à K (barre des cycles), écritures proposées, pièces à demander, revue N / N-1.</li>
          <li><strong>Mois</strong> (gestion courante) : choisissez le mois en haut (flèches ‹ ›) ; il vaut pour les trois onglets. <strong>Pièces manquantes</strong> (cumulées depuis le début de l'exercice) à demander au client, <strong>Contrôles de saisie</strong> (factures ou règlements passés sur un autre tiers, factures en double, <strong>numérotation des factures de vente</strong> sur toutes les écritures de produits 70, 75 et 77, factures et avoirs, par série : numéros manquants, doublons, ordre chronologique ; opérations restées en compte d'attente avec l'<strong>affectation suggérée</strong> quand le même libellé a déjà été affecté dans le FEC, et lettré pour un compte de tiers ; fournisseurs débiteurs et clients créditeurs à la fin du mois) et <strong>TVA</strong> (bêta). « Marquer le mois comme revu » signe le contrôle de la saisie du mois (et coche l'étape de contrôle de la mission « Saisie » du mois, si votre modèle en comporte une).</li>
          <li><strong>Rapprochement bancaire</strong> : rapprochement de l'exercice, et relevé du mois détaillé (état de rapprochement, écritures à passer).</li>
          <li><strong>Lettrage et LCR</strong> (lettrage des tiers, écritures LCR), <strong>Paie</strong> (éditions Silae), <strong>Immobilisations</strong> (état du module immo) : le FEC ouvert est repris, rien à redéposer ; un fichier déposé sur ces onglets va à leur outil.</li>
          <li><strong>TVA</strong> : contrôle de la TVA de l'exercice et TVA du mois.</li>
          <li><strong>Consultation</strong> : graphiques mensuels (CA, charges, trésorerie), SIG et bilan, balance, journaux et tiers, conformité du fichier.</li>
        </ul>
        L'onglet Synthèse, Mois, Révision A–K ou Consultation utilisé en dernier est repris à l'ouverture du FEC suivant. Les outils qui n'ont pas besoin d'un FEC (calcul de TVA, cotisations TNS, écritures LCR, relevés PDF, lettrage d'un grand livre, ratios sectoriels) sont regroupés dans le menu sous « Outils sans FEC ».</li>
      <li><strong>Archive Pennylane (.zip FEC + justificatifs)</strong> : déposez directement l'archive exportée. Le FEC est extrait et seuls les <em>noms</em> des justificatifs sont lus (les fichiers ne sont pas ouverts) : les écritures sans justificatif sont listées exactement dans la synthèse, et les pièces à demander (client, mensuel, mails fournisseurs) citent ces factures précises au lieu d'estimations. Si les noms de fichiers ne reprennent pas les n° de pièce, l'application le signale et revient aux estimations.</li>
      <li><strong>Conformité</strong> : les contrôles de l'article A47 A-1 du LPF (colonnes, dates, équilibre, numérotation…), avec des exemples de lignes en cause.</li>
      <li><strong>Points de révision</strong> : caisse créditrice, comptes d'attente, clients créditeurs, fournisseurs débiteurs, compte courant d'associé débiteur, doublons, dimanches et jours fériés, loi de Benford.</li>
      <li>SIG, bilan simplifié, balance, graphiques mensuels, journaux et tiers ; export Excel complet.</li>
      <li><strong>Imputation sur le bon compte de tiers</strong> (bêta ; onglets Achats et Clients, Trésorerie pour une officine, et contrôles de saisie du mois) : factures et règlements passés sur un autre fournisseur ou client que le leur, repérés par le libellé (il désigne un autre tiers et ne ressemble pas aux libellés habituels du compte) ou par le montant (règlement sans facture de ce montant sur son compte, mais du montant exact d'une facture d'un autre tiers, non réglée). Chaque cas se traite un par un, et l'écriture de reclassement entre les deux comptes est proposée dans l'onglet Écritures.</li>
      <li><strong>Contrôle de la TVA de l'exercice</strong> (Espace FEC, onglet TVA → « Contrôle TVA »), sur le modèle de la feuille de travail TVA, du début de l'exercice à la fin du mois d'arrêté (par défaut le dernier mois dont l'OD de TVA est comptabilisée). Les montants en gris sont calculés d'après le FEC ; une case saisie remplace le calcul, et se vide pour y revenir. Les saisies sont conservées, chiffrées, dans le dossier, pour l'exercice.
        <ul>
          <li><strong>Récapitulatif des déclarations</strong> : une ligne par mois (ou trimestre), pré-remplie d'après l'OD de TVA de la période, retrouvée par le mois cité dans son libellé (« TVA juin 2026 ») ou, à défaut, par ses montants. Base de chaque taux = TVA ÷ taux, arrondie à l'euro : remplacez-la par la base déclarée. TVA collectée, report de crédit (crédit de la période précédente, plus un acompte imputé), TVA à payer et crédit sont recalculés ; « Écart OD » compare le net calculé à l'OD passée. Régularisations à déduire et à ajouter, CA déclaré, TVA sur le CA déclaré.</li>
          <li><strong>TVA collectée</strong> : solde de chaque compte de produits rangé dans la colonne de son taux. Le taux vient du paramétrage de l'onglet TVA, sinon des écritures de vente (base × taux = TVA), sinon du libellé : les numéros de comptes peuvent changer d'un dossier à l'autre. Il se change dans le tableau, pour le dossier. Les écritures d'inventaire reconnues (factures et avoirs à établir, produits constatés d'avance, extournes) sont retirées d'office ; les autres corrections se saisissent. Contrôle en bases : CA × taux (A) contre TVA comptabilisée (B) = solde des comptes de TVA collectée de ce taux + à-nouveaux + OD de TVA ± différences de lettrage.</li>
          <li><strong>TVA sur les encaissements</strong> : CA ± créances, avances, créances douteuses et effets de début et de fin de période (HT par taux), comparé au CA déclaré. Les avances sont reprises des comptes 419 dont le libellé donne le taux ; les soldes 411, 416 et 413 du FEC et la TVA non exigible comptabilisée sont rappelés pour la saisie.</li>
          <li><strong>TVA déductible</strong> : soldes des comptes de TVA déductible avant l'OD de la période (acquisitions intracommunautaires, immobilisations, autres biens et services, TVA sur encaissements, crédit), moins la TVA des prestations de services non réglées, comparés à la TVA déduite par l'OD. Annexe des fournisseurs créditeurs : « Services » est coché d'office quand leurs factures portent surtout sur des comptes de services, avec le taux le plus fréquent de leurs factures ; les choix restent d'un exercice à l'autre.</li>
          <li><strong>Soldes de TVA après OD</strong> : solde théorique ((créances − avances) × taux ; TVA des prestations non réglées) contre solde réel des comptes, écart et base HT correspondante.</li>
          <li><strong>Import des CA3 déposées</strong> (bouton « Importer des CA3 (PDF) » du récapitulatif) : PDF du formulaire 3310-CA3-SD, copie téléchargée de l'espace professionnel ou édition du logiciel, une ou plusieurs déclarations par fichier. Les lignes sont lues par leur code : bases des lignes 08, 09, 9B… (autoliquidations A3, B2, B4 reportées à part), E1, E2, F2, 15 et 5B, 17, 19, 20, 21, 22 et 2C, 26. Le SIREN et la période sont vérifiés ; le badge CA3 compare les lignes 27 et 28 au calcul ; « × » efface une période. Un PDF scanné (image) ne peut pas être lu.</li>
          <li><strong>Créances et avances clients par taux</strong> : quand les factures clients sont lettrées dans leur majorité, les factures non réglées à l'ouverture et à l'arrêté sont retrouvées par le lettrage (date du dernier règlement), ventilées en HT par les comptes de produits de chaque facture ; les règlements non encore affectés sont des avances ; à-nouveaux et règlements sont répartis au prorata des factures du client. Sinon, importez la liste des factures non réglées exportée du logiciel de facturation (Excel ou CSV : n° de facture, date, HT, TVA, TTC, reste dû, taux ou statut, reconnus par l'intitulé des colonnes).</li>
          <li><strong>OD de régularisation proposée</strong> : une écriture par écart des soldes après OD, qui ramène le compte de TVA à son solde théorique contre un écart d'arrondi (658 ou 758) sous le seuil, sinon contre la TVA à régulariser (4458) à reprendre sur la prochaine déclaration. Les écarts au-delà du seuil ne sont pas cochés d'office. Export au format FEC (import ACD, Pennylane), Excel ou CSV.</li>
          <li><strong>Portefeuille</strong> (Espace FEC → Plus → Plusieurs dossiers) : le contrôle de la TVA de chaque dossier, avec ses saisies et CA3 déjà importées : écart avec les OD, contrôle en bases, encaissements, TVA déductible, soldes après OD, nombre d'OD proposées ; « Ouvrir » mène à l'onglet Contrôle TVA du dossier. Feuille « Contrôle TVA » dans l'export Excel.</li>
        </ul></li>
      <li><strong>Contrôle de la TVA</strong> (bêta ; Espace FEC, onglet TVA → TVA du mois), pour le mois ou le trimestre choisi. Tout est calculé sur les comptes, comme dans votre logiciel :
        <ul>
          <li><strong>TVA de la période</strong> = mouvements des comptes 445 des écritures de la période, hors écritures de déclaration (OD de TVA) et de paiement ; la TVA collectée est détaillée par taux quand les comptes le sont. Les mêmes montants se retrouvent dans la balance des comptes 445 de la période ;</li>
          <li><strong>déclaration comptabilisée</strong> : l'OD de TVA de la période est retrouvée et comparée, ligne à ligne (collectée, déductible, crédit imputé, net) ; le paiement à la DGFiP aussi. Les reliquats (TVA restée en compte d'une période précédente, par exemple une facture saisie après la déclaration) sont signalés ;</li>
          <li><strong>chiffre d'affaires et TVA par taux</strong> : base des comptes de produits de chaque taux × taux, comparée à la TVA comptabilisée, avec la liste des écritures en cause ; ventes sans TVA sur des comptes taxables ; exportations, livraisons intracommunautaires, opérations non imposables et hors champ (ROSP, subventions) mises à part ;</li>
          <li><strong>paramétrage des comptes</strong> : la nature des comptes de TVA et le taux de chaque compte de produits sont déduits des numéros, des libellés et des écritures (honoraires de dispensation à 2,1 % par exemple). Corrigez-les si besoin : le paramétrage est conservé dans le dossier ;</li>
          <li><strong>brouillon de CA3</strong> aux lignes du formulaire 3310-CA3-SD en vigueur (A1, A2, A3 et B2 pour l'autoliquidation, E1, E2, F2 ; 08, 09, 9B ; 2,1 % en ligne T6 en France continentale, 11 dans les DOM ; 16, 17, 19 à 23, 25 à 28), <strong>comptes de TVA</strong> (solde d'ouverture, opérations, déclaration, paiement, solde de fin) et export Excel des écritures de TVA de la période ;</li>
          <li><strong>contrôles</strong> de la TVA déductible : autoliquidation non déduite, véhicules de tourisme, carburants, hébergement, cadeaux, dépenses personnelles, TVA supérieure à 20 %, factures sans TVA ;</li>
          <li><strong>montants déclarés</strong> : le net noté dans le suivi mensuel (ou saisi ici avec les lignes 01, 16 et 23) est comparé au calcul ; la <strong>concordance</strong> récapitule toutes les périodes de l'exercice ;</li>
          <li><strong>Valider le contrôle</strong> le note au journal, coche l'étape « Contrôle et calcul de la TVA » de la mission du mois et y note le montant s'il ne l'est pas. Les points se traitent un par un ; « Ne plus signaler » vaut pour tous les mois du dossier. Export Excel et impression PDF.</li>
        </ul></li>
      <li><strong>Dossier de révision</strong> (onglet « Cycles A à K ») : les comptes sont rangés comme dans un dossier papier — A régularité formelle (comptes d'attente, virements internes 58, à-nouveaux comparés à la clôture N-1, sens des soldes), B trésorerie et financement (banques, caisse, emprunts, comptes courants 45, frais bancaires 627, charges et produits financiers), C achats et fournisseurs, D charges externes, E ventes et clients, F stocks et en-cours, G immobilisations, H personnel, I État, J capitaux propres et provisions, K autres comptes. Chaque cycle a ses contrôles, ses <strong>comptes</strong> (solde, N-1 ou ouverture, variation ; compte de bilan non soldé ou variation significative surligné, case « justifié » et commentaire repris dans la revue N / N-1) et ses <strong>pièces</strong> attendues d'après les comptes mouvementés : celles du client s'ajoutent à la demande de pièces du bilan, et leur statut (demandé, reçu) s'affiche dans le cycle. Les points généraux (doublons, dates atypiques…) figurent dans leur cycle avec le même statut que dans la synthèse. Un cycle sans compte ni point est « sans objet ». Cycle G : dans l'onglet « Immobilisations » de l'Espace FEC, déposez l'état des immobilisations édité depuis le module immo (PDF texte : lignes « Compte n° », une ligne par fiche avec début d'exercice, acquisitions, sorties et fin, sous-totaux « immobilisation » et « comptabilité » ; si le PDF ne se lit pas, collez son texte). Le FEC de l'analyse est repris : les écritures passées sur les comptes d'immobilisations (classe 2, hors 28 et 29, à-nouveaux exclus) sont rapprochées des fiches de leur compte au centime (une facture ventilée sur plusieurs fiches, ou plusieurs factures sur une fiche, jusqu'à quatre éléments). Résultat : les écritures sans fiche (fiches à créer, avec fournisseur, TVA et TTC tirés de l'écriture, et l'indice « même montant sur une fiche d'un autre compte »), le contrôle du solde de chaque compte (écart expliqué par ces écritures ou à expliquer), les avoirs sans sortie et les sorties sans écriture, les fiches sans écriture, à copier pour Excel. La lecture du PDF est contrôlée sur les sous-totaux imprimés. La synthèse est enregistrée dans le dossier : contrôles du cycle, tableau des immobilisations « Édition lue », valeur brute de l'état dans la colonne « Selon pièce » des comptes. Cycle H : le bouton « Faire le cadrage de la paie » ouvre l'onglet « Paie » avec le FEC de l'analyse ; déposez-y les éditions Silae (journal ou récapitulatif de paie, détail des cotisations, solde de repos). Le cadre « Cadrage de la paie » du cycle reprend ensuite le statut de chaque compte, les comptes à justifier figurent dans les contrôles et les éditions lues sont des pièces établies. Un rapprochement fait avec l'ancienne version reste repris dans les contrôles tant que le cadrage n'est pas refait. La paie étant faite au cabinet, aucune pièce de paie n'est demandée au client.
        <ul>
          <li><strong>Achats</strong> : factures en double, dettes échues, délais de paiement réels (lettrage, ou règlements imputés sur les factures les plus anciennes), TVA déductible anormale ou absente, autoliquidation, pièces hors exercice, factures non parvenues, nouveaux fournisseurs.</li>
          <li><strong>Charges externes</strong> : tableau par compte avec les mois mouvementés, charges récurrentes manquantes, charges constatées d'avance probables, bénéficiaires DAS2, dépenses personnelles possibles, amendes, cadeaux, notes de frais.</li>
          <li><strong>Clients</strong> : trous et doublons dans la numérotation des factures, créances échues et dépréciation, délais d'encaissement, factures sans TVA, facturation de fin d'exercice, factures à établir et produits constatés d'avance de N-1 non extournés.</li>
          <li><strong>Trésorerie</strong> : découverts, espèces de 1 000 € ou plus, caisse, virements internes non soldés, comptes dormants, flux par nature et mouvements importants.</li>
          <li>Les tableaux des délais de paiement de l'article D441-6 du code de commerce sont calculés pour les clients et les fournisseurs (échéance réglable).</li>
        </ul></li>
      <li><strong>Feuille de travail</strong> : chaque point de contrôle reçoit un statut (justifié, corrigé, pièce demandée, sans objet) et un commentaire ; « Marquer le cycle comme revu » signe la revue. Tout est conservé, chiffré, dans le dossier, et une nouvelle analyse du même exercice reprend où vous en étiez. « Dossier de travail (PDF) » imprime l'ensemble.</li>
      <li><strong>Élément par élément</strong> : dépliez un contrôle pour traiter chaque facture, dépense ou opération (statut et commentaire), ou tous ceux encore à traiter en une fois ; « Masquer les éléments traités » allège la liste. Un élément justifié ou sans objet écarte l'écriture proposée correspondante, et un élément en « pièce demandée » s'ajoute aux pièces à demander.</li>
      <li><strong>Mémoire du dossier</strong> : « Justifié » sur un élément (ex. un abonnement validé) ou « Ne plus signaler » sur un contrôle : il ne sera plus remonté lors des analyses suivantes de ce dossier, y compris l'année prochaine. La liste se gère depuis la fiche du dossier (Mémoire de révision).</li>
      <li><strong>Écritures</strong> : les écritures de clôture sont proposées à partir des contrôles (charges et produits constatés d'avance, extournes oubliées de l'exercice précédent, dépréciation des créances échues, annulation des factures en double, reclassement des amendes, TVA sur cadeaux, autoliquidation, impôt sur les sociétés estimé, et pour une situation les charges annuelles au prorata). Ajustez les montants et les contreparties, puis exportez le fichier pour <strong>ACD</strong> ou <strong>Pennylane</strong> (format FEC, Excel ou CSV). Faites un premier import sur un dossier test.</li>
      <li><strong>Situation</strong> : avec le FEC N-1, la situation est comparée à la <strong>même période</strong> de l'exercice précédent, et une projection du résultat de fin d'exercice est calculée, avec les charges annuelles absentes de la situation.</li>
      <li><strong>Anonymiser un FEC</strong> (bouton « Anonymiser un FEC » de l'analyse) : avant d'envoyer un FEC à un tiers (support, mise au point de l'application). Tout se fait sur l'appareil ; la correspondance entre noms et pseudonymes n'est jamais enregistrée. Mode « clients » (par défaut) : noms des clients (comptes 41, ventes, encaissements), des salariés, associés, dirigeants et exploitant, de toute personne repérée par un prénom ou une civilité (« M. », « Mme », « chantier », « SCI »…), et du dossier (d'après sa fiche) remplacés ; fournisseurs conservés. Mode « tout » : tout mot hors vocabulaire comptable remplacé. IBAN, cartes, n° de sécurité sociale, plaques, téléphones, e-mails, SIREN / SIRET et n° longs toujours masqués ; colonnes ajoutées par le logiciel et lignes décalées traitées strictement. Montants, encodage et structure conservés (montants modifiables en option). Relisez les mots conservés : un client au nom fait de mots courants (« Café du Port ») est signalé, un clic le remplace.</li>
      <li><strong>Portefeuille FEC</strong> (Espace FEC → Plus → « Plusieurs dossiers », ou « Portefeuille FEC » sur la page Dossiers) : sélectionnez les FEC de plusieurs dossiers en une fois ; ils sont analysés l'un après l'autre, rattachés par SIREN et classés par charge de révision (anomalies, points à traiter, pièces, écritures). Le nombre de pièces manquantes ouvre directement l'espace Mois du dossier.</li>
      <li><strong>Pièces manquantes</strong> (Espace FEC, onglet Mois) : l'application liste, pour les achats et les ventes, tout ce qui manque depuis le début de l'exercice jusqu'à la fin du mois choisi : factures des fournisseurs et clients habituels absentes, règlements et encaissements sans facture, dépenses payées directement, numéros de facture manquants et opérations en compte d'attente. Toute pièce encore manquante dans le FEC est à demander, qu'elle ait déjà été demandée ou non, jusqu'à ce qu'elle soit comptabilisée. Le choix « Toutes / Factures fournisseurs / Factures clients » limite la demande aux pièces des comptes fournisseurs ou des comptes clients ; les opérations en compte d'attente (47) restent toujours demandées. La liste « Comptes de tiers » permet d'écarter un compte fournisseur ou client (en officine, les comptes de tiers payant, techniques et de patients sont écartés d'office). Ces deux choix sont conservés dans le dossier et repris à la demande suivante. La demande mensuelle ne reprend rien des journaux d'achats et de ventes (reconnus à leur libellé, leur code ou leurs écritures) : factures ou avoirs sans justificatif, numéros de facture manquants et factures habituelles absentes ne sont plus demandés. Elle porte sur les règlements fournisseurs et encaissements clients sans facture et les opérations en compte d'attente de tous les autres journaux (banque, caisse, OD, effets…), et sur les charges externes payées directement (locations, assurances, cotisations…), sans les immobilisations. La catégorie « Justificatifs de dépenses payées directement » se coche en entier (demande occasionnelle, décochée par défaut) ; pour chaque groupe de paiements, choisissez « Factures » ou « Échéancier » (proposé d'office pour les assurances). Ces choix sont conservés dans le dossier. Sur un compte lettré, chaque règlement non lettré est demandé, à-nouveaux détaillés compris (datés du règlement d'origine, libellé sans date ni journal ; un avoir antérieur n'est pas demandé). En officine, la case « Enlever les paiements de moins de … € » de la partie « Factures fournisseurs » (montant au choix, 100 € par défaut) allège la demande mensuelle (choix conservé dans le dossier). Pour chaque fournisseur, choisissez « Factures » ou « Relevé » (fournisseur dont seuls les relevés sont saisis), choix conservé dans le dossier. La liste Excel précise le mode de règlement trouvé dans le FEC : « Facture, réglée par LCR / virement / CB / prélèvement / chèque ». Envoyez la demande dès la saisie du mois : elle complète la demande mensuelle en cours du dossier (une seule par exercice), et le mail rappelle ce qui est toujours attendu. Le Portefeuille indique ce nombre pour chaque dossier.</li>
      <li><strong>Demandes directes aux fournisseurs</strong> (sous les pièces à demander) : pour chaque laboratoire, grossiste ou fournisseur dont des factures manquent, un mail avec le n° de compte client du dossier chez lui, la dénomination et la période, qui demande le duplicata des factures et un relevé de compte. Le n° client et l'e-mail sont conservés dans le dossier. Le FEC ne contient pas les pièces jointes : seules les écritures sont analysées.</li>
      <li><strong>Pièces à demander</strong> (Espace FEC, onglet Révision A–K) : choisissez « Situation » ou « Bilan » et la date d'arrêté ; l'application liste les relevés bancaires manquants, les factures récurrentes absentes, les paiements sans facture, les opérations en compte d'attente (47), les acquisitions d'immobilisations et, pour un bilan, les documents de clôture et les questions sur les créances et dettes anciennes. Chaque opération en compte d'attente porte un menu pour la ranger en <em>Ventes et encaissements</em>, <em>Factures fournisseurs</em> ou <em>Opérations diverses</em> ; le libellé demandé suit la rubrique (facture, facture de vente, avoir ou justificatif). « Créer la demande » prépare le mail et une mission dont chaque étape est une pièce : cochez-les à réception, la relance ne reprendra que ce qui manque. « Liste Excel pour le client » produit un document prêt à envoyer ou à imprimer.</li>
      <li><strong>Revue N / N-1</strong> : chargez aussi le FEC de l'exercice précédent. Les postes et les comptes sont comparés, et les variations au-delà du seuil de signification sont listées pour que vous les justifiez. Contrôles de cohérence automatiques : TVA / CA, charges sociales / salaires, amortissements, intérêts, capitaux propres, points fiscaux. La <strong>note de synthèse</strong> s'imprime ou s'enregistre en PDF pour le rendez-vous bilan.</li>
      <li><strong>Rapprochement</strong> : importez le relevé bancaire (CFONB / EBICS, OFX, CAMT.053, CSV ou Excel de la banque, ou relevé PDF au texte sélectionnable, comme l'édition « Relevé bancaire » d'ACD). L'application affiche les opérations non comptabilisées (avec l'affectation suggérée d'après les opérations au même libellé déjà comptabilisées), les écritures absentes du relevé et l'état de rapprochement. Les opérations non comptabilisées s'ajoutent aux pièces à demander.</li>
      <li><strong>Profil d'analyse</strong> : « Structure classique » ou « Officine ». Il vient de la fiche du dossier (« Activité (analyse FEC) ») ; à défaut, il est détecté sur le contenu du FEC (tiers payant, TVA à 2,1 %, honoraires). Le choix « Profil » en haut de l'analyse l'enregistre dans la fiche du dossier rattaché. Si le FEC ne ressemble pas à l'activité indiquée, l'application le signale.</li>
      <li><strong>Officine</strong> : onglet <strong>Tiers payant</strong> (encours AMO, AMC et patients, ancienneté, rejets probables : précis si les comptes 411 sont lettrés, estimés d'après les délais normaux de paiement sinon), onglet <strong>CA et TVA</strong> par taux (2,1 %, 5,5 %, 10 %, 20 %), taux de marque, remises fournisseurs, écarts de caisse. Les comptes 511 (CB, chèques à encaisser) sont traités comme des comptes de transit, et les alertes inadaptées à une officine (Benford, clients créditeurs, ouverture le dimanche) sont retirées. Les pièces à demander ajoutent l'inventaire du LGO, les relevés de tiers payant et de rejets, les RFA et la ROSP.</li>
      <li>Rattachez l'analyse au dossier (reconnu par son SIREN) pour en garder la synthèse, et créez en un clic une <strong>mission de revue</strong> dont les étapes sont les points relevés.</li>
    </ul>`)}
    ${item('Calcul de TVA', `<ul>
      <li>Menu <strong>Calcul TVA</strong> : choisissez le taux (20 %, 10 %, 5,5 % ou 2,1 %) puis saisissez le montant connu, HT, TVA ou TTC : les deux autres se calculent pendant la frappe (TVA arrondie au centime, TTC = HT + TVA).</li>
      <li><strong>Le même montant aux quatre taux</strong> : le tableau donne HT, TVA et TTC pour chaque taux, utile pour retrouver le taux appliqué sur une facture.</li>
      <li><strong>Ventilation par taux</strong> : pour un ticket, une facture ou un Z de caisse à plusieurs taux (officine), saisissez le TTC (ou le HT) de chaque taux : HT, TVA, TTC et totaux. « Copier le tableau » le colle tel quel dans Excel.</li>
      <li>Un clic sur un résultat le copie, au format Excel (virgule décimale, sans séparateur de milliers). Rien n'est enregistré.</li>
    </ul>`)}
    ${item('Ratios sectoriels', `<ul>
      <li>Menu <strong>Ratios sectoriels</strong> (ou bouton « Ratios sectoriels » de la fiche du dossier) : ratios de l'INSEE (Ésane 2023, publié le 18/09/2025) par code NAF, pour les quelque 670 sous-classes. Les données sont dans l'application : la recherche ne se connecte à aucun site.</li>
      <li>Recherchez par code (69.20Z, 6920, 692, 47, M) ou par libellé (boulangerie, pharmacie). Le fil en haut remonte au groupe, à la division et à la section. Les ratios comptables sont publiés au niveau du <strong>groupe</strong> (3 chiffres), avec le rappel 2022 ; « Comparer à » propose aussi la division par taille (microentreprises, PME, ETI et grandes entreprises), souvent plus pertinente pour une TPE.</li>
      <li><strong>Le dossier</strong> : choisissez-le (son code NAF, renseigné sur sa fiche, ouvre directement son secteur), puis saisissez ses chiffres en k€ ou cliquez sur <strong>Reprendre l'analyse FEC</strong> si un FEC est ouvert. Écart et position (au-dessus, en dessous, dans la norme à ± 10 %) se calculent pendant la frappe. La saisie est conservée, chiffrée, dans le dossier. « Copier pour Excel » copie les deux tableaux.</li>
      <li>Chiffres repris du FEC (approximations à partir de la balance, à contrôler avec la liasse) : CA = 70 ; achats et charges externes = 60 à 62 ; VA, EBE, résultat courant et résultat net du SIG ; frais de personnel = 64 ; intérêts = 661 ; CAF = résultat + dotations (681, 686, 687) − reprises (781, 786, 787) + VNC des cessions (675) − produits de cession (775) − quote-part de subventions (777) ; capitaux propres, dettes financières et total du bilan simplifié ; immobilisations corporelles brutes = 21 à 23 ; capital d'exploitation = immobilisations nettes + stocks + créances − dettes fournisseurs, fiscales, sociales et autres ; investissements = débits de l'exercice des 21 et acquisitions nettes des 23 ; créances clients = soldes débiteurs des 41 (hors 419) ; dettes fournisseurs = soldes créditeurs des 401, 403 et 408. L'effectif, le CA export et le taux de TVA ne sont pas dans le FEC : saisissez-les.</li>
      <li>Les ratios INSEE sont des ratios <strong>agrégés</strong> (somme des numérateurs sur somme des dénominateurs) : ils reflètent surtout les grandes entreprises du secteur. « S » = secret statistique.</li>
    </ul>`)}
    ${item('Comparer deux FEC', `<ul>
      <li>Espace FEC → Plus → <strong>Comparer deux FEC</strong> : déposez le <strong>FEC de référence</strong> (celui qui a été déclaré) et le <strong>FEC à comparer</strong>, du même exercice (fichier .txt ou archive .zip de Pennylane). « ⇄ » inverse les deux. Tout se fait sur l'appareil ; rien n'est conservé.</li>
      <li><strong>Rapprochement</strong> : les comptes sont ramenés à 6 chiffres (60610000 et 6061000009 → 606100) et les tiers rapprochés par leur nom, formes juridiques ignorées (« Garage du Centre SARL » = « GARAGE DU CENTRE »). Les comptes numérotés ou nommés autrement (banque 51200000 ↔ 5121001, tiers au nom tronqué) sont reconnus sur les opérations identiques et listés dans « Correspondances » : ce ne sont pas des écarts. Les écritures sont rapprochées par date, montant et compte, quels que soient le journal, le n° d'écriture et la pièce.</li>
      <li><strong>Écritures</strong> : absentes du FEC comparé (à saisir ou à justifier), en plus (doublons, saisies d'un seul côté), modifiées (autre date jusqu'à deux mois d'écart, autre montant, autre compte, lignes en plus ou en moins). Une même somme ventilée autrement (paie en une ou deux écritures, ventes centralisées par jour ou par mois) n'est pas un écart. Chaque écriture se déplie pour voir ses lignes.</li>
      <li><strong>Balance, Tiers, À-nouveaux</strong> : soldes comparés compte par compte (à-nouveaux compris), écart en débit (D) ou crédit (C) ; les à-nouveaux, souvent globaux dans un logiciel et détaillés par pièce dans l'autre, sont comparés par compte. <strong>Synthèse</strong> : chiffre d'affaires, résultat, trésorerie, clients, fournisseurs… et écarts par rubrique.</li>
      <li>Si les deux FEC ne couvrent pas la même période (export en cours d'exercice), seule la <strong>période commune</strong> est comparée ; une case permet de tout comparer. Des SIREN ou des dates de clôture différents dans les noms des fichiers sont signalés.</li>
      <li><strong>Exporter en Excel</strong> : synthèse, écritures absentes, en plus et modifiées (ligne par ligne), ventilations, balance et correspondances. Le fichier n'est pas chiffré.</li>
    </ul>`)}
    ${item('Rapprocher un relevé', `<ul>
      <li>Menu <strong>Rapprochement</strong> (sur ordinateur) : déposez le <strong>relevé bancaire</strong> de n'importe quelle banque (PDF au texte sélectionnable, CSV ou Excel exporté de la banque en ligne, OFX, QIF, MT940, CAMT.053 / 052 / 054, CFONB ; plusieurs relevés à la suite si besoin) et le <strong>FEC du journal de banque</strong> du mois (dans ACD : export FEC limité au journal de banque et à la période ; le FEC complet convient aussi). Le compte de banque est choisi d'après les opérations retrouvées, et se change dans la liste.</li>
      <li><strong>Appariement</strong> : même montant à quelques jours près (tolérance réglable), puis regroupements (une remise de chèques pour plusieurs écritures, ou l'inverse). Restent : <strong>opérations non comptabilisées</strong>, <strong>écritures absentes du relevé</strong> (chèques non encaissés, remises en cours), <strong>montants différents</strong> (même opération saisie pour un autre montant ; « chiffres inversés » si ce sont les mêmes chiffres), <strong>sens inversés</strong> (débit au lieu de crédit) et <strong>doublons</strong> (écriture passée deux fois).</li>
      <li><strong>Différence entre le relevé et le journal</strong> : écart des mouvements du mois, entièrement ventilé entre ces catégories. <strong>État de rapprochement</strong> : solde du relevé (lu sur le relevé ou à saisir), opérations non comptabilisées, écritures absentes, doublons et écarts, solde comptable attendu, comparé au solde du compte (à saisir depuis ACD, le FEC du seul journal n'ayant pas d'à-nouveau) ; l'écart inexpliqué doit être nul.</li>
      <li><strong>Écritures à passer</strong> : les opérations non comptabilisées, banque contre le compte suggéré (celui des écritures au même libellé, ou de l'écriture d'une opération identique du relevé) ou 471 à défaut, en FEC (import ACD ou Pennylane) ou en Excel. À vérifier avant validation. <strong>Exporter en Excel</strong> : état de rapprochement et listes.</li>
      <li>Tout se fait sur l'appareil ; rien n'est conservé, et le verrouillage efface l'écran.</li>
    </ul>`)}
    ${item('Écritures LCR pour ACD', `<ul>
      <li>Menu <strong>Écritures LCR</strong> (ou glisser-déposer sur la page) : <strong>1.</strong> le <strong>listing fournisseurs</strong> du dossier (Excel .xlsx ou CSV : colonne A le compte, colonne B l'intitulé), ou son <strong>FEC</strong> (comptes 401 et 404 : compte auxiliaire et intitulé), retenu pour les fois suivantes ; dans l'onglet « Écritures LCR » de l'Espace FEC, les comptes fournisseurs viennent du FEC ouvert, rien à déposer ; <strong>2.</strong> les <strong>relevés LCR</strong> en PDF, autant qu'on veut : relevé d'effets à payer du <strong>Crédit Agricole</strong> (n° du relevé, date de règlement, date d'édition, contrat, effets avec leur avis ; R ou S = rejeté) ou relevé de lettres de change du <strong>CIC</strong> (n° de relevé, date de règlement, compte et total, effets ; un montant refusé rejette l'effet). Le nombre d'effets et le total sont contrôlés, un relevé déjà chargé est ignoré, les effets rejetés ne sont pas repris. Le dossier est repéré par le contrat ou le compte : chargez les relevés d'un seul dossier à la fois.</li>
      <li><strong>3. Comptes fournisseurs</strong> : chaque tireur est rapproché d'un compte du listing par les mots de son nom (formes juridiques et mots courants ignorés) : « Trouvé », « À confirmer » (rapprochement partiel ou plusieurs comptes possibles), « Sans compte ». Saisissez ou choisissez un code, ou confirmez la suggestion : le choix est retenu pour ce dossier (données chiffrées) et repris le mois suivant (« Mémorisé ») ; un code absent du listing est « À créer » dans ACD avant l'import. « Oublier » revient à la suggestion.</li>
      <li><strong>4. Écritures et import ACD</strong> : une OD par relevé (pièce = n° du relevé, date de règlement ou d'édition), chaque effet payé au débit du fournisseur, le total au crédit du compte de contrepartie (58003000 par défaut, réglable avec le code journal et la longueur des libellés). Fichier d'import ACD (.txt : point-virgule, sans en-tête, montants avec virgule, caractères Windows), tableau de contrôle Excel ou copie du contenu ; le fichier est bloqué tant qu'un tireur n'a pas de compte. Au premier export, le listing est associé au dossier : il est repris automatiquement aux relevés suivants, comme les réglages.</li>
      <li>Les relevés restent sur l'appareil et ne sont pas conservés ; les fichiers téléchargés ne sont pas chiffrés : supprimez-les après l'import.</li>
    </ul>`)}
    ${item('Relevés PDF → Excel', `<ul>
      <li>Menu <strong>Relevés PDF</strong> (ou glisser-déposer des PDF sur la page) : choisissez un ou plusieurs relevés bancaires PDF. Toutes les banques : l'édition « Relevé bancaire » d'ACD et les relevés en colonnes Date (avec ou sans l'année, « 05.10 », ou en lettres, « 5 oct. 2026 » : l'année se déduit de la période ou de la date d'édition du relevé) / Date de valeur / Libellé / Débit et Crédit (ou Dépenses et Recettes, Sortie et Entrée, Argent sortant et entrant, Money out et in) ou un seul Montant signé, avec ou sans colonne Solde, sur plusieurs pages (lignes « À reporter » et « Report » écartées, montant écrit sur la ligne suivant la date rattaché à son opération). Sans en-tête reconnu (débits et crédits sous une même colonne « Mouvements », relevé par rubriques « Virements reçus », « Prélèvements »…), les colonnes de montants sont déduites de leur position : la lecture n'est retenue que si elle retrouve au centime les soldes, les totaux ou le solde progressif du relevé. Le PDF doit contenir du texte : un relevé scanné (image) ne peut pas être lu.</li>
      <li>Chaque relevé est contrôlé : total des dépenses et des recettes comparé à la ligne « Total » du relevé, solde initial − dépenses + recettes comparé au solde final, solde progressif ligne par ligne, opérations hors de la période. Un écart est signalé avant le téléchargement. Les libellés sur deux lignes sont réunis ; les lignes « Solde », « Total » et les pieds de page sont écartés.</li>
      <li><strong>Format du fichier</strong> : « Montant signé » (Date, Libellé, Montant ; dépense en négatif), format des modèles d'import de transactions de Pennylane et de la plupart des logiciels, ou « Débit et crédit » (deux colonnes de montants). Plusieurs relevés donnent un seul fichier, dans l'ordre chronologique. Dates au format date d'Excel, montants en nombres.</li>
      <li>Tout se fait sur l'appareil ; rien n'est conservé. Le fichier Excel n'est pas chiffré : supprimez-le après l'import.</li>
    </ul>`)}
    ${item('Fonctions en bêta', `<p>Les fonctions marquées <span class="badge beta">bêta</span> sont récentes et n'ont pas encore été validées sur de vrais dossiers du cabinet. Utilisez-les, mais <strong>contrôlez leurs résultats</strong> avant de vous y fier, et signalez les écarts constatés pour qu'elles soient corrigées.</p>
      <ul>
        <li><strong>Contrôle de la TVA</strong> (Espace FEC, onglet TVA → TVA du mois) : refait sur les seuls comptes (mouvements des comptes 445 et des comptes de produits de la période), à comparer à votre outil de contrôle sur quelques dossiers avant de vous y fier.</li>
        <li><strong>Imputation sur le bon compte de tiers</strong> : factures et règlements passés sur un autre fournisseur ou client (cycles Achats, Clients, Trésorerie et contrôles de saisie du mois).</li>
        <li><strong>Justificatifs d'une archive Pennylane</strong> : rapprochement des écritures et des justificatifs par n° de pièce, à partir des seuls noms de fichiers.</li>
      </ul>`)}
    ${item('Rappels dans votre agenda', `<p>Paramètres → <strong>Échéances dans mon agenda</strong> : téléchargez un fichier .ics et ouvrez-le avec votre agenda pour être prévenu même application fermée. Par défaut, seuls les numéros de dossier apparaissent dans l'agenda.</p>`)}
    ${item('PC et téléphone', `<p>Chaque appareil possède son propre coffre chiffré ; il n'y a volontairement aucun serveur. Pour retrouver vos données sur un autre appareil : exportez une sauvegarde chiffrée, puis <strong>Restaurer une sauvegarde</strong> sur l'autre appareil avec le même mot de passe. La sauvegarde automatique placée dans un dossier synchronisé du cabinet facilite ce transfert.</p>`)}
    ${item('Sécurité et secret professionnel', `<ul>
      <li>Les données sont chiffrées (AES-256) et ne quittent jamais l'appareil. Aucun compte, aucun serveur, aucun traceur.</li>
      <li>Le <strong>mode discret</strong> (icône œil) remplace les noms par les numéros de dossier : utile en rendez-vous ou en déplacement.</li>
      <li>L'application se verrouille seule après quelques minutes d'inactivité. Sans le mot de passe, <strong>personne</strong> ne peut lire les données, pas même vous : notez-le en lieu sûr.</li>
      <li>Sur un appareil personnel protégé par un code, Paramètres → <strong>Ne plus demander le mot de passe sur cet appareil</strong> ouvre l'application directement. Les données restent chiffrées sur le disque, mais quiconque accède à votre session peut les lire. Le mot de passe reste nécessaire pour restaurer une sauvegarde.</li>
      <li>Les exports Excel et CSV ne sont pas chiffrés : supprimez-les après usage.</li>
    </ul>`)}`;
}
